/* Слой · оригинальный проект портфолио RMRNM. Без отправки данных и аналитики. */
(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const palettes={navy:{name:'Глубокий синий',image:'living',description:'Синий задаёт спокойный ритм. Орех добавляет тепла, а светлый текстиль оставляет пространство для воздуха.',materials:['Тёмный орех','Синий пигмент','Натуральный лён']},wine:{name:'Тёплый бордо',image:'bedroom',description:'Бордовый раскрывается в мягком вечернем свете. Тёплый лён и латунь добавляют тактильности и камерного уюта.',materials:['Бордовая штукатурка','Натуральный лён','Состаренная латунь']},forest:{name:'Лесная тишина',image:'kitchen',description:'Глубокая зелень встречается с рисунком дерева и спокойным камнем. Палитра, в которой легко замедлиться.',materials:['Зелёная эмаль','Тёмный орех','Природный камень']}};
const projects=[{id:'living',title:'Тихая глубина',meta:'Квартира · 84 м² · визуальная концепция',description:'Глубокие синие панели объединяют комнату, а тёмный орех и зелёный диван поддерживают ощущение тепла. Бордовое кресло — небольшой личный акцент.'},{id:'bedroom',title:'Тёплый полутон',meta:'Квартира · 96 м² · визуальная концепция',description:'Тактильная бордовая стена, светлый лён и тёплая латунь создают камерное настроение. Тёмное дерево связывает спальню с общей палитрой дома.'},{id:'kitchen',title:'Ближе к лесу',meta:'Загородный дом · 158 м² · визуальная концепция',description:'Зелёные фасады и ореховые панели обрамляют каменный остров. Дневной свет подчёркивает фактуры, а просторная композиция оставляет место для общения.'}];
let palette='navy',galleryIndex=0,briefText='';
const menu=$('.menu-button'),nav=$('#nav');
const closeMenu=()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Открыть меню');nav.classList.remove('open');};
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');nav.classList.toggle('open',open);});
$$('#nav a').forEach(a=>a.addEventListener('click',closeMenu));
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$$('.project').forEach(p=>{p.hidden=filter!=='all'&&p.dataset.type!==filter;});const grid=$('.project-grid');grid.classList.toggle('is-filtered',filter!=='all');grid.classList.toggle('one-result',$$('.project').filter(p=>!p.hidden).length===1);}));
const gallery=$('#gallery');
const showProject=index=>{galleryIndex=(index+projects.length)%projects.length;const p=projects[galleryIndex];$('#gallery-image').src='assets/'+p.id+'.webp';$('#gallery-image').alt=p.title+' — авторская визуальная концепция интерьера';$('#gallery-title').textContent=p.title;$('#gallery-meta').textContent=p.meta;$('#gallery-description').textContent=p.description;$('#gallery-count').textContent=(galleryIndex+1)+' / '+projects.length;};
$$('[data-project]').forEach(button=>button.addEventListener('click',()=>{showProject(projects.findIndex(p=>p.id===button.dataset.project));gallery.showModal();}));
$('#gallery-prev').addEventListener('click',()=>showProject(galleryIndex-1));$('#gallery-next').addEventListener('click',()=>showProject(galleryIndex+1));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(gallery.open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showProject(galleryIndex+(e.key==='ArrowRight'?1:-1));}});
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));
$$('[data-palette]').forEach(button=>button.addEventListener('click',()=>{palette=button.dataset.palette;const p=palettes[palette];$$('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#palette-image').src='assets/'+p.image+'.webp';$('#palette-image').alt=p.name+' — интерьерная палитра RMRNM';$('#palette-description').textContent=p.description;$('#palette-materials').innerHTML=p.materials.map(m=>'<span>'+esc(m)+'</span>').join('');}));
$('#use-palette').addEventListener('click',()=>{$('#brief-palette').value=palette;$('#brief').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#brief-palette').focus({preventScroll:true});});
const area=$('#area'),range=$('#area-range'),packageSelect=$('#package');
const rates={full:4800,concept:2800};
const estimate=()=>{if(!area.validity.valid||!area.value){$('#estimate').textContent='Укажите площадь';$('#rate-note').textContent='От 15 до 500 м²';return;}const n=Number(area.value),rate=rates[packageSelect.value];$('#estimate').textContent=money(n*rate);$('#rate-note').textContent=n+' м² × '+money(rate)+'/м²';};
area.addEventListener('input',()=>{if(area.validity.valid&&area.value)range.value=area.value;estimate();});range.addEventListener('input',()=>{area.value=range.value;estimate();});packageSelect.addEventListener('change',estimate);estimate();
$('#brief-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const form=new FormData(e.target);const n=Number(form.get('area')),style=palettes[form.get('palette')],format=form.get('package')==='full'?'Полный дизайн-проект':'Концепция интерьера',cost=n*rates[form.get('package')],wishes=String(form.get('wishes')||'').trim().slice(0,500);const lines=[['Пространство',String(form.get('property'))],['Площадь',n+' м²'],['Формат',format],['Настроение',style.name]];
$('#brief-summary').innerHTML='<dl>'+lines.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+(wishes?'<p><strong>Ваши пожелания</strong><br>'+esc(wishes)+'</p>':'')+'<p class="summary-cost">Пример бюджета: '+money(cost)+'</p>';
briefText=['СЛОЙ — бриф вашего пространства','Портфолио RMRNM','',...lines.map(([k,v])=>k+': '+v),'Материалы: '+style.materials.join(', '),'',wishes?'Пожелания: '+wishes:'Пожелания пока не указаны.','','Пример бюджета дизайн-проекта: '+money(cost),'Демонстрационный тариф: '+money(rates[form.get('package')])+'/м². Ремонт и мебель не включены.','','Это локальный пример брифа для портфолио. Заявка не отправлена, расчёт не является коммерческим предложением.'].join('\n');$('#copy-status').textContent='';$('#brief-dialog').showModal();});
$('#download-brief').addEventListener('click',()=>{if(!briefText)return;const url=URL.createObjectURL(new Blob(['\ufeff'+briefText],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SLOY-RMRNM-brief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);});
$('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(briefText);$('#copy-status').textContent='Бриф скопирован.';}catch{$('#copy-status').textContent='Не удалось скопировать. Сохраните бриф кнопкой «Скачать бриф .txt».';}});
$('#about-project').addEventListener('click',()=>$('#project-info').showModal());
})();
